namespace Scheduling;

/// <summary>Places jobs onto the most suitable available resource.</summary>
public sealed class Scheduler
{
    public IReadOnlyList<string> PlaceJobs(IEnumerable<Job> jobs, IReadOnlyList<Resource> resources)
    {
        var placements = new List<string>();

        foreach (var job in jobs)
        {
            if (string.IsNullOrEmpty(job.RequiredSkill))
                continue;

            var resource = FindBestResource(job, resources);
            placements.Add(FormatPlacement(job, resource));
        }

        return placements;
    }

    private static Resource? FindBestResource(Job job, IReadOnlyList<Resource> resources)
    {
        Resource? bestResource = null;

        foreach (var resource in resources)
        {
            if (!IsAvailableFor(resource, job))
                continue;

            if (bestResource == null || resource.Calendar.Count < bestResource.Calendar.Count)
                bestResource = resource;
        }

        return bestResource;
    }

    private static bool IsAvailableFor(Resource resource, Job job) =>
        resource.Skills.Contains(job.RequiredSkill) && resource.Calendar.Count <= 20;

    private static string FormatPlacement(Job job, Resource? resource)
    {
        if (resource == null)
            return $"{job.Id}:UNPLACED";

        var suffix = GetPlacementSuffix(job, resource);
        return $"{job.Id}:{resource.Name}{suffix}";
    }

    private static string GetPlacementSuffix(Job job, Resource resource)
    {
        if (RequiresOvertime(job, resource))
            return ":OT";

        return job.Priority > 8 ? ":URGENT" : string.Empty;
    }

    private static bool RequiresOvertime(Job job, Resource resource) =>
        (job.Priority > 5 && resource.Calendar.Count > 10) ||
        job.Duration.TotalHours > 8;
}
